def average(nums):
    if not nums:
        return 0
    return round(sum(nums) / len(nums), 1)

def above_average(nums):
    if not nums:
        return []
    avg = sum(nums) / len(nums)
    return [n for n in nums if n > avg]

def biggest(nums):
    if not nums:
        return None
    best = nums[0]
    for n in nums:
        if n > best:
            best = n
    return best
